const PAGES = {"u1.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>GRC Serve | Part 1: Servant Heart Profile</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  *{margin:0;padding:0;box-sizing:border-box}\n  :root{\n    --blk:#231F20;--gry:#6B6B6B;--glt:#F5F5F5;--wht:#FFFFFF;\n    --tdk:#547878;--tdkr:#3B6261;--t2:#7DA3A4;\n    --ex:#FFF4EE;--exa:#D4704A;--dr:#FFFBEE;--dra:#C8900A;\n    --de:#F0EEFF;--dea:#7C5CBF;--st:#EEF8F0;--sta:#2A8A50;\n    --fn:'Montserrat',sans-serif;--rd:14px;--sh:0 4px 28px rgba(84,120,120,.12);\n  }\n  html{font-family:var(--fn);color:var(--blk);-webkit-tap-highlight-color:transparent}\n  body{min-height:100vh;background:linear-gradient(160deg,#EEF5F8 0%,#EBF4F4 50%,#EAF1EE 100%)}\n  .app{max-width:640px;margin:0 auto;padding:14px 10px 60px}\n  .card{background:var(--wht);border-radius:var(--rd);box-shadow:var(--sh);overflow:hidden;margin-bottom:12px}\n  .top-hdr{padding:22px 18px 16px;text-align:center;border-bottom:2px solid #EEF5F8}\n  .top-hdr h1{font-size:1.05rem;font-weight:800;color:var(--tdkr);letter-spacing:.3px}\n  .sec-badge{display:inline-block;margin-top:10px;background:linear-gradient(135deg,var(--tdk),var(--t2));color:var(--wht);font-size:.67rem;font-weight:700;padding:5px 15px;border-radius:20px;letter-spacing:.8px;text-transform:uppercase;box-shadow:0 2px 10px rgba(84,120,120,.3)}\n  .hdr-sub{font-size:.78rem;color:var(--gry);margin-top:10px;line-height:1.55;padding:0 6px}\n  .scalekey{display:flex;gap:5px;flex-wrap:wrap;justify-content:center;font-size:.62rem;color:var(--gry);margin-top:10px}\n  .scalekey span{background:var(--glt);border-radius:6px;padding:3px 8px}\n  .prog-wrap{padding:13px 18px 11px;position:sticky;top:0;background:var(--wht);z-index:10;border-bottom:1px solid #EEF5F8}\n  .prog-meta{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;font-size:.72rem;font-weight:700;color:var(--gry)}\n  .prog-bar{height:8px;background:#EEF5F8;border-radius:99px;overflow:hidden}\n  .prog-fill{height:100%;width:0;background:linear-gradient(90deg,var(--tdk),var(--t2));transition:width .25s}\n  .q{padding:16px 18px;border-bottom:1px solid #F1F5F6}\n  .q .word{font-size:1.05rem;font-weight:600;margin-bottom:12px;color:var(--blk)}\n  .i-scale{display:flex;gap:6px}\n  .i-scale label{flex:1;text-align:center;font-size:.62rem;color:var(--gry);cursor:pointer;padding:8px 2px;border:1.5px solid #E3EBEC;border-radius:10px;transition:all .15s}\n  .i-scale input{display:none}\n  .i-scale label.sel{border-color:var(--tdk);background:var(--tdk);color:var(--wht);font-weight:700;transform:scale(1.03)}\n  .i-scale .num{display:block;font-size:1rem;font-weight:700;margin-bottom:2px}\n  .nav{padding:16px 18px}\n  .btn-sb{width:100%;padding:15px 20px;border-radius:10px;font-size:.92rem;font-weight:700;border:none;cursor:pointer;font-family:var(--fn);background:linear-gradient(135deg,var(--blk),var(--tdkr));color:var(--wht);box-shadow:0 3px 13px rgba(59,98,97,.32)}\n  .btn-sb:disabled{opacity:.45;box-shadow:none}\n  .result{padding:22px 18px}\n  .result .code{font-size:2.3rem;font-weight:800;color:var(--tdkr);letter-spacing:1px}\n  .result .role{background:var(--glt);border-radius:10px;padding:14px;margin-top:14px;font-size:.9rem}\n  .foot{text-align:center;color:var(--gry);font-size:.68rem;padding:14px 0 4px}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <div class=\"card\">\n    <div class=\"top-hdr\">\n      <h1>Gateway Revival Church</h1>\n      <div class=\"sec-badge\">Part 1 · Servant Heart Profile</div>\n      <div class=\"hdr-sub\">Rate how much each word describes <b>the real, consistent you</b> — not your best day. There are no right answers. 32 words, about 4 minutes.</div>\n      <div class=\"scalekey\"><span>1 Not me</span><span>2 Usually not</span><span>3 Sometimes</span><span>4 Usually me</span><span>5 IS me</span></div>\n    </div>\n    <div class=\"prog-wrap\">\n      <div class=\"prog-meta\"><span>Servant Heart Profile</span><span id=\"prog\">0 of 32</span></div>\n      <div class=\"prog-bar\"><div class=\"prog-fill\" id=\"fill\"></div></div>\n    </div>\n    <form id=\"form\"></form>\n    <div class=\"nav\"><button class=\"btn-sb\" id=\"submit\" disabled>See my serving profile</button></div>\n    <div id=\"result\"></div>\n  </div>\n  <div class=\"foot\">Gateway Revival Church — Benoni · Ministry Training</div>\n</div>\n<script>\n/* ── Identity carry-through (ported from GRC DNA) — keeps every section on the\n   SAME GHL contact so the registration selfie stays attached and no duplicate\n   contact is created. Priority: ?contactId= / path cid (authoritative). ──────*/\nconst GRC_ID=(function(){try{const q=new URLSearchParams(location.search);\n  let cid=(location.pathname.match(/\\/u1\\/([A-Za-z0-9]+)/)||[])[1]||q.get('contactId')||q.get('contact_id')||'';\n  const em=(q.get('email')||'').trim().toLowerCase();\n  if(cid){localStorage.setItem('grc_cid',cid);if(em)localStorage.setItem('grc_cid_email',em);}\n  return{fromUrl:!!cid,cid:cid||localStorage.getItem('grc_cid')||'',email:em||localStorage.getItem('grc_cid_email')||''};\n}catch(e){return{fromUrl:false,cid:'',email:''}}})();\nconst CID=GRC_ID.cid||'preview';\n\nconst GROUPS={\n  EX:{name:\"Expressive\",acc:\"#D4704A\",words:[\"Outgoing\",\"Enthusiastic\",\"Talkative\",\"Warm\",\"Engaging\",\"Cheerful\",\"Persuasive\",\"Spontaneous\"]},\n  DR:{name:\"Driver\",acc:\"#C8900A\",words:[\"Assertive\",\"Decisive\",\"Ambitious\",\"Competitive\",\"Direct\",\"Determined\",\"Take-charge\",\"Goal-driven\"]},\n  DE:{name:\"Deep\",acc:\"#7C5CBF\",words:[\"Analytical\",\"Thoughtful\",\"Introspective\",\"Detailed\",\"Reflective\",\"Precise\",\"Cautious\",\"Principled\"]},\n  ST:{name:\"Steady\",acc:\"#2A8A50\",words:[\"Calm\",\"Patient\",\"Supportive\",\"Reliable\",\"Loyal\",\"Even-tempered\",\"Cooperative\",\"Dependable\"]}\n};\nconst ROLE={EX:\"Welcome Usher — warmth and first contact at the door\",\n  DR:\"Floor / Head-Usher track — decisive crowd flow and direction\",\n  DE:\"Ministry Support / Safety — attentive, careful, boundary-aware\",\n  ST:\"Ministry Support (Catcher) & Follow-Up — calm, dependable presence\"};\nconst HOW={EX:\"You serve best where people are met and made to feel welcome.\",\n  DR:\"You serve best where someone must take charge and keep things moving.\",\n  DE:\"You serve best where attentiveness and care for detail protect people.\",\n  ST:\"You serve best where steady, dependable, behind-the-scenes care is needed.\"};\nlet ITEMS=[];\nObject.keys(GROUPS).forEach(g=>GROUPS[g].words.forEach((w,i)=>ITEMS.push({g,w,k:g+i})));\nITEMS=ITEMS.map((it,i)=>({...it,o:(i*7+3)%ITEMS.length})).sort((a,b)=>a.o-b.o);\nconst SKEY=\"grc_usher_p1_\"+CID, ans=JSON.parse(localStorage.getItem(SKEY)||\"{}\");\nconst form=document.getElementById(\"form\");\nITEMS.forEach(it=>{\n  const q=document.createElement(\"div\");q.className=\"q\";\n  q.innerHTML='<div class=\"word\">'+it.w+'</div><div class=\"i-scale\">'+\n    [1,2,3,4,5].map(v=>'<label><input type=\"radio\" name=\"'+it.k+'\" value=\"'+v+'\"><span class=\"num\">'+v+'</span></label>').join('')+'</div>';\n  form.appendChild(q);\n  if(ans[it.k]){const r=q.querySelector('input[value=\"'+ans[it.k]+'\"]');if(r){r.checked=true;r.closest('label').classList.add('sel');}}\n});\nfunction refresh(){const done=Object.keys(ans).length;\n  document.getElementById(\"prog\").textContent=done+\" of \"+ITEMS.length;\n  document.getElementById(\"fill\").style.width=(done/ITEMS.length*100)+\"%\";\n  document.getElementById(\"submit\").disabled=done<ITEMS.length;}\nform.addEventListener(\"change\",e=>{if(e.target.name){ans[e.target.name]=+e.target.value;localStorage.setItem(SKEY,JSON.stringify(ans));\n  e.target.closest(\".i-scale\").querySelectorAll(\"label\").forEach(l=>l.classList.remove(\"sel\"));\n  e.target.closest(\"label\").classList.add(\"sel\");refresh();}});\nrefresh();\ndocument.getElementById(\"submit\").addEventListener(\"click\",async()=>{\n  const sum={EX:0,DR:0,DE:0,ST:0};ITEMS.forEach(it=>sum[it.g]+=(ans[it.k]||0));\n  const rank=Object.keys(sum).sort((a,b)=>sum[b]-sum[a]);const P=rank[0],S=rank[1],code=P+\"-\"+S;\n  document.getElementById(\"result\").innerHTML='<div class=\"result\"><div class=\"code\">'+code+'</div>'+\n    '<div><b>'+GROUPS[P].name+'</b> (primary) · <b>'+GROUPS[S].name+'</b> (secondary)</div>'+\n    '<p style=\"margin-top:8px\">'+HOW[P]+'</p>'+\n    '<div class=\"role\"><b>Suggested serving role:</b><br>'+ROLE[P]+'</div>'+\n    '<p style=\"color:var(--gry);font-size:.8rem;margin-top:12px\">Part 1 of 3 saved. Continue straight to Part 2 below.</p>'+\n    '<div class=\"nav\"><a class=\"btn-sb\" style=\"display:block;text-align:center;text-decoration:none;line-height:1.2\" href=\"/u2/'+CID+'\">Continue to Part 2 &rarr;</a></div></div>';\n  document.getElementById(\"result\").scrollIntoView({behavior:\"smooth\"});\n  /* Submit to the NEW usher worker only — never the live grc-pdf-generator.\n     The Continue button is rendered synchronously above, so progression never\n     depends on this network call succeeding. */\n  try{await fetch(\"/section-submit\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},\n    body:JSON.stringify({course:\"usher\",section:\"u1\",contactId:CID,scores:sum,code:code,primary:P,secondary:S})});}catch(e){}\n});\n</script>\n</body>\n</html>\n","u2.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>GRC Serve | Part 2: Serve-Ready Check</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  *{margin:0;padding:0;box-sizing:border-box}\n  :root{--blk:#231F20;--gry:#6B6B6B;--glt:#F5F5F5;--wht:#FFFFFF;--tdk:#547878;--tdkr:#3B6261;--t2:#7DA3A4;--fn:'Montserrat',sans-serif;--rd:14px;--sh:0 4px 28px rgba(84,120,120,.12)}\n  html{font-family:var(--fn);color:var(--blk);-webkit-tap-highlight-color:transparent}\n  body{min-height:100vh;background:linear-gradient(160deg,#EEF5F8 0%,#EBF4F4 50%,#EAF1EE 100%)}\n  .app{max-width:640px;margin:0 auto;padding:14px 10px 60px}\n  .card{background:var(--wht);border-radius:var(--rd);box-shadow:var(--sh);overflow:hidden;margin-bottom:12px}\n  .top-hdr{padding:22px 18px 16px;text-align:center;border-bottom:2px solid #EEF5F8}\n  .top-hdr h1{font-size:1.05rem;font-weight:800;color:var(--tdkr);letter-spacing:.3px}\n  .sec-badge{display:inline-block;margin-top:10px;background:linear-gradient(135deg,var(--tdk),var(--t2));color:var(--wht);font-size:.67rem;font-weight:700;padding:5px 15px;border-radius:20px;letter-spacing:.8px;text-transform:uppercase;box-shadow:0 2px 10px rgba(84,120,120,.3)}\n  .hdr-sub{font-size:.78rem;color:var(--gry);margin-top:10px;line-height:1.55;padding:0 6px}\n  .scalekey{display:flex;gap:5px;flex-wrap:wrap;justify-content:center;font-size:.6rem;color:var(--gry);margin-top:10px}\n  .scalekey span{background:var(--glt);border-radius:6px;padding:3px 8px}\n  .prog-wrap{padding:13px 18px 11px;position:sticky;top:0;background:var(--wht);z-index:10;border-bottom:1px solid #EEF5F8}\n  .prog-meta{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;font-size:.72rem;font-weight:700;color:var(--gry)}\n  .prog-bar{height:8px;background:#EEF5F8;border-radius:99px;overflow:hidden}\n  .prog-fill{height:100%;width:0;background:linear-gradient(90deg,var(--tdk),var(--t2));transition:width .25s}\n  .q{padding:16px 18px;border-bottom:1px solid #F1F5F6}\n  .q .stmt{font-size:.98rem;font-weight:600;margin-bottom:12px;line-height:1.4}\n  .i-scale{display:flex;gap:6px}\n  .i-scale label{flex:1;text-align:center;font-size:.55rem;color:var(--gry);cursor:pointer;padding:8px 2px;border:1.5px solid #E3EBEC;border-radius:10px;transition:all .15s}\n  .i-scale input{display:none}\n  .i-scale label.sel{border-color:var(--tdk);background:var(--tdk);color:var(--wht);font-weight:700;transform:scale(1.03)}\n  .i-scale .num{display:block;font-size:1rem;font-weight:700;margin-bottom:2px}\n  .nav{padding:16px 18px}\n  .btn-sb{width:100%;padding:15px 20px;border-radius:10px;font-size:.92rem;font-weight:700;border:none;cursor:pointer;font-family:var(--fn);background:linear-gradient(135deg,var(--blk),var(--tdkr));color:var(--wht);box-shadow:0 3px 13px rgba(59,98,97,.32)}\n  .btn-sb:disabled{opacity:.45;box-shadow:none}\n  .result{padding:22px 18px}\n  .result .band{font-size:1.9rem;font-weight:800;color:var(--tdkr)}\n  .dom{display:flex;justify-content:space-between;border-top:1px solid #EEF5F8;padding:8px 0;font-size:.85rem}\n  .foot{text-align:center;color:var(--gry);font-size:.68rem;padding:14px 0 4px}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <div class=\"card\">\n    <div class=\"top-hdr\">\n      <h1>Gateway Revival Church</h1>\n      <div class=\"sec-badge\">Part 2 · Serve-Ready Check</div>\n      <div class=\"hdr-sub\">Answer based on your <b>real, consistent pattern of life</b> — not your best day, not your ideal self. Be honest before God. 30 statements, about 5 minutes.</div>\n      <div class=\"scalekey\"><span>1 Rarely/Never</span><span>2 Occasionally</span><span>3 Sometimes</span><span>4 Often</span><span>5 Consistently</span></div>\n    </div>\n    <div class=\"prog-wrap\">\n      <div class=\"prog-meta\"><span>Serve-Ready Check</span><span id=\"prog\">0 of 30</span></div>\n      <div class=\"prog-bar\"><div class=\"prog-fill\" id=\"fill\"></div></div>\n    </div>\n    <form id=\"form\"></form>\n    <div class=\"nav\"><button class=\"btn-sb\" id=\"submit\" disabled>See my readiness</button></div>\n    <div id=\"result\"></div>\n  </div>\n  <div class=\"foot\">Gateway Revival Church — Benoni · Ministry Training</div>\n</div>\n<script>\nconst GRC_ID=(function(){try{const q=new URLSearchParams(location.search);\n  let cid=(location.pathname.match(/\\/u2\\/([A-Za-z0-9]+)/)||[])[1]||q.get('contactId')||q.get('contact_id')||'';\n  const em=(q.get('email')||'').trim().toLowerCase();\n  if(cid){localStorage.setItem('grc_cid',cid);if(em)localStorage.setItem('grc_cid_email',em);}\n  return{fromUrl:!!cid,cid:cid||localStorage.getItem('grc_cid')||'',email:em||localStorage.getItem('grc_cid_email')||''};\n}catch(e){return{fromUrl:false,cid:'',email:''}}})();\nconst CID=GRC_ID.cid||'preview';\nconst DOMAINS={\n CI:{name:\"Character & Integrity\",items:[[\"I keep my word even when it costs me something.\",0],[\"I am the same person in private that I am in public.\",0],[\"I tell the truth even when a small lie would be easier.\",0],[\"When I make a mistake, I own it rather than cover it.\",0],[\"I bend the rules when I think no one will notice.\",1]]},\n HT:{name:\"Humility & Teachability\",items:[[\"I accept correction without becoming defensive.\",0],[\"I am quick to say 'I was wrong' when I am.\",0],[\"I actively ask others for feedback on how I serve.\",0],[\"I value other people's input above my own preferences.\",0],[\"I struggle to take instruction from people younger or less experienced than me.\",1]]},\n RF:{name:\"Reliability & Faithfulness\",items:[[\"I arrive on time and ready for what I have committed to.\",0],[\"I finish what I start, even the unseen tasks.\",0],[\"People can depend on me to do what I said I would.\",0],[\"I show up consistently, not only when I feel like it.\",0],[\"I often cancel or drop commitments at the last minute.\",1]]},\n CD:{name:\"Confidentiality & Discretion\",items:[[\"I keep private matters private, even from close friends.\",0],[\"I can be trusted with sensitive information.\",0],[\"I handle other people's struggles quietly and with care.\",0],[\"I resist the urge to share news that isn't mine to share.\",0],[\"I find it hard not to repeat something interesting I have heard.\",1]]},\n SA:{name:\"Submission to Authority\",items:[[\"I willingly follow the leaders God has placed over me.\",0],[\"I support a decision once it is made, even if I disagreed.\",0],[\"I honour those in charge rather than undermine them.\",0],[\"I raise concerns respectfully and through the right channel.\",0],[\"I do things my own way even when I have been asked not to.\",1]]},\n ES:{name:\"Emotional Steadiness\",items:[[\"I stay calm when situations become tense or chaotic.\",0],[\"I control my reactions rather than let my emotions lead.\",0],[\"Under pressure, others would describe me as steady.\",0],[\"I recover quickly when things do not go as planned.\",0],[\"I get flustered or short-tempered when things go wrong.\",1]]}\n};\nlet ITEMS=[];\nObject.keys(DOMAINS).forEach(d=>DOMAINS[d].items.forEach((it,i)=>ITEMS.push({d,t:it[0],r:it[1],k:d+i})));\nITEMS=ITEMS.map((it,i)=>({...it,o:(i*11+5)%ITEMS.length})).sort((a,b)=>a.o-b.o);\nconst SKEY=\"grc_usher_p2_\"+CID, ans=JSON.parse(localStorage.getItem(SKEY)||\"{}\");\nconst form=document.getElementById(\"form\");\nITEMS.forEach(it=>{\n  const q=document.createElement(\"div\");q.className=\"q\";\n  q.innerHTML='<div class=\"stmt\">'+it.t+'</div><div class=\"i-scale\">'+\n    [1,2,3,4,5].map(v=>'<label><input type=\"radio\" name=\"'+it.k+'\" value=\"'+v+'\"><span class=\"num\">'+v+'</span></label>').join('')+'</div>';\n  form.appendChild(q);\n  if(ans[it.k]){const r=q.querySelector('input[value=\"'+ans[it.k]+'\"]');if(r){r.checked=true;r.closest('label').classList.add('sel');}}\n});\nfunction refresh(){const done=Object.keys(ans).length;\n  document.getElementById(\"prog\").textContent=done+\" of \"+ITEMS.length;\n  document.getElementById(\"fill\").style.width=(done/ITEMS.length*100)+\"%\";\n  document.getElementById(\"submit\").disabled=done<ITEMS.length;}\nform.addEventListener(\"change\",e=>{if(e.target.name){ans[e.target.name]=+e.target.value;localStorage.setItem(SKEY,JSON.stringify(ans));\n  e.target.closest(\".i-scale\").querySelectorAll(\"label\").forEach(l=>l.classList.remove(\"sel\"));\n  e.target.closest(\"label\").classList.add(\"sel\");refresh();}});\nrefresh();\ndocument.getElementById(\"submit\").addEventListener(\"click\",async()=>{\n  const dom={};let raw=0;\n  Object.keys(DOMAINS).forEach(d=>{let s=0;DOMAINS[d].items.forEach((it,i)=>{let v=ans[d+i]||0;if(it[1])v=6-v;s+=v;});dom[d]=s;raw+=s;});\n  const norm=Math.round(raw/150*100);const band=norm>=80?\"Ready\":norm>=60?\"Developing\":\"Not-yet\";\n  const flag=(dom.CD/25*100<60)||(dom.SA/25*100<60);\n  let rows=Object.keys(DOMAINS).map(d=>{const p=Math.round(dom[d]/25*100);const lbl=p>=75?\"Strong\":p>=55?\"Developing\":\"Attention\";\n    return '<div class=\"dom\"><span>'+DOMAINS[d].name+'</span><span>'+p+'% · '+lbl+'</span></div>';}).join('');\n  document.getElementById(\"result\").innerHTML='<div class=\"result\"><div class=\"band\">'+band+'</div>'+\n    '<div>Overall readiness score: <b>'+norm+'/100</b></div>'+rows+\n    (flag?'<p style=\"color:#a3400f;margin-top:12px\"><b>Pastoral note:</b> a conversation is recommended before active service.</p>':'')+\n    '<p style=\"color:var(--gry);font-size:.8rem;margin-top:12px\">Part 2 of 3 saved. Continue straight to Part 3 below.</p>'+\n    '<div class=\"nav\"><a class=\"btn-sb\" style=\"display:block;text-align:center;text-decoration:none;line-height:1.2\" href=\"/u3/'+CID+'\">Continue to Part 3 &rarr;</a></div></div>';\n  document.getElementById(\"result\").scrollIntoView({behavior:\"smooth\"});\n  /* Continue button rendered synchronously above — progression never depends on this call. */\n  try{await fetch(\"/section-submit\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},\n    body:JSON.stringify({course:\"usher\",section:\"u2\",contactId:CID,domains:dom,normalised:norm,band:band,pastoral_flag:flag})});}catch(e){}\n});\n</script>\n</body>\n</html>\n","u3.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>GRC Serve | Part 3: Ministry Fit &amp; Gifting</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  *{margin:0;padding:0;box-sizing:border-box}\n  :root{--blk:#231F20;--gry:#6B6B6B;--glt:#F5F5F5;--wht:#FFFFFF;--tdk:#547878;--tdkr:#3B6261;--t2:#7DA3A4;--gold:#C8900A;--fn:'Montserrat',sans-serif;--rd:14px;--sh:0 4px 28px rgba(84,120,120,.12)}\n  html{font-family:var(--fn);color:var(--blk);-webkit-tap-highlight-color:transparent}\n  body{min-height:100vh;background:linear-gradient(160deg,#EEF5F8 0%,#EBF4F4 50%,#EAF1EE 100%)}\n  .app{max-width:640px;margin:0 auto;padding:14px 10px 60px}\n  .card{background:var(--wht);border-radius:var(--rd);box-shadow:var(--sh);overflow:hidden;margin-bottom:12px}\n  .top-hdr{padding:22px 18px 16px;text-align:center;border-bottom:2px solid #EEF5F8}\n  .top-hdr h1{font-size:1.05rem;font-weight:800;color:var(--tdkr);letter-spacing:.3px}\n  .sec-badge{display:inline-block;margin-top:10px;background:linear-gradient(135deg,var(--tdk),var(--t2));color:var(--wht);font-size:.67rem;font-weight:700;padding:5px 15px;border-radius:20px;letter-spacing:.8px;text-transform:uppercase;box-shadow:0 2px 10px rgba(84,120,120,.3)}\n  .hdr-sub{font-size:.78rem;color:var(--gry);margin-top:10px;line-height:1.55;padding:0 6px}\n  .scalekey{display:flex;gap:5px;flex-wrap:wrap;justify-content:center;font-size:.6rem;color:var(--gry);margin-top:10px}\n  .scalekey span{background:var(--glt);border-radius:6px;padding:3px 8px}\n  .prog-wrap{padding:13px 18px 11px;position:sticky;top:0;background:var(--wht);z-index:10;border-bottom:1px solid #EEF5F8}\n  .prog-meta{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;font-size:.72rem;font-weight:700;color:var(--gry)}\n  .prog-bar{height:8px;background:#EEF5F8;border-radius:99px;overflow:hidden}\n  .prog-fill{height:100%;width:0;background:linear-gradient(90deg,var(--tdk),var(--t2));transition:width .25s}\n  .q{padding:16px 18px;border-bottom:1px solid #F1F5F6}\n  .q .tag{font-size:.6rem;text-transform:uppercase;letter-spacing:.6px;color:var(--gold);font-weight:700;margin-bottom:4px}\n  .q .stmt{font-size:.98rem;font-weight:600;margin-bottom:12px;line-height:1.4}\n  .i-scale{display:flex;gap:6px}\n  .i-scale label{flex:1;text-align:center;font-size:.55rem;color:var(--gry);cursor:pointer;padding:8px 2px;border:1.5px solid #E3EBEC;border-radius:10px;transition:all .15s}\n  .i-scale input{display:none}\n  .i-scale label.sel{border-color:var(--tdk);background:var(--tdk);color:var(--wht);font-weight:700;transform:scale(1.03)}\n  .i-scale .num{display:block;font-size:1rem;font-weight:700;margin-bottom:2px}\n  .nav{padding:16px 18px}\n  .btn-sb{width:100%;padding:15px 20px;border-radius:10px;font-size:.92rem;font-weight:700;border:none;cursor:pointer;font-family:var(--fn);background:linear-gradient(135deg,var(--blk),var(--tdkr));color:var(--wht);box-shadow:0 3px 13px rgba(59,98,97,.32)}\n  .btn-sb:disabled{opacity:.45;box-shadow:none}\n  .result{padding:22px 18px}\n  .result h2{font-size:1.05rem;font-weight:800;color:var(--tdkr);margin-bottom:6px}\n  .gift{display:flex;justify-content:space-between;border-top:1px solid #EEF5F8;padding:8px 0;font-size:.85rem}\n  .gift b{color:var(--tdkr)}\n  .role{background:var(--glt);border-radius:10px;padding:14px;margin-top:14px;font-size:.9rem}\n  .foot{text-align:center;color:var(--gry);font-size:.68rem;padding:14px 0 4px}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <div class=\"card\">\n    <div class=\"top-hdr\">\n      <h1>Gateway Revival Church</h1>\n      <div class=\"sec-badge\">Part 3 · Ministry Fit &amp; Gifting</div>\n      <div class=\"hdr-sub\">Rate how true each statement is of you. Some ask what you <b>love</b> (passion), others what has actually <b>shown up</b> over time (evidence). 24 statements, about 4 minutes.</div>\n      <div class=\"scalekey\"><span>1 Not at all</span><span>2 A little</span><span>3 Somewhat</span><span>4 Mostly</span><span>5 Strongly</span></div>\n    </div>\n    <div class=\"prog-wrap\">\n      <div class=\"prog-meta\"><span>Ministry Fit &amp; Gifting</span><span id=\"prog\">0 of 24</span></div>\n      <div class=\"prog-bar\"><div class=\"prog-fill\" id=\"fill\"></div></div>\n    </div>\n    <form id=\"form\"></form>\n    <div class=\"nav\"><button class=\"btn-sb\" id=\"submit\" disabled>See my ministry fit</button></div>\n    <div id=\"result\"></div>\n  </div>\n  <div class=\"foot\">Gateway Revival Church — Benoni · Ministry Training</div>\n</div>\n<script>\nconst GRC_ID=(function(){try{const q=new URLSearchParams(location.search);\n  let cid=(location.pathname.match(/\\/u3\\/([A-Za-z0-9]+)/)||[])[1]||q.get('contactId')||q.get('contact_id')||'';\n  const em=(q.get('email')||'').trim().toLowerCase();\n  if(cid){localStorage.setItem('grc_cid',cid);if(em)localStorage.setItem('grc_cid_email',em);}\n  return{fromUrl:!!cid,cid:cid||localStorage.getItem('grc_cid')||'',email:em||localStorage.getItem('grc_cid_email')||''};\n}catch(e){return{fromUrl:false,cid:'',email:''}}})();\nconst CID=GRC_ID.cid||'preview';\nconst GIFTS={\n \"Helps & Service\":[\"I genuinely enjoy practical tasks that support others behind the scenes.\",\"People regularly rely on me to get practical things done, and I follow through.\"],\n \"Hospitality\":[\"I love making people feel welcome and at ease.\",\"Others have told me they felt genuinely welcomed because of me.\"],\n \"Mercy\":[\"I am drawn to comfort people who are hurting or distressed.\",\"People in pain often seek me out because I show real compassion.\"],\n \"Administration\":[\"I enjoy organising people, tasks and details so things run smoothly.\",\"I have a track record of keeping things orderly and well-coordinated.\"],\n \"Leadership\":[\"I am energised by taking responsibility and guiding a team toward a goal.\",\"Others naturally look to me to take the lead, and they follow.\"],\n \"Discernment\":[\"I pay close attention to what is really going on beneath the surface.\",\"My read on people and situations has repeatedly proven accurate.\"],\n \"Encouragement\":[\"I love building others up and spurring them on.\",\"People say they feel strengthened after talking with me.\"],\n \"Faith\":[\"I readily trust God for things others find hard to believe.\",\"My confidence in God has held steady and encouraged others in hard times.\"],\n \"Giving\":[\"I find real joy in giving generously of my time and resources.\",\"I consistently give beyond what is expected of me.\"],\n \"Intercession\":[\"I am drawn to pray earnestly and persistently for others.\",\"I have kept praying for people and situations over long periods.\"],\n \"Shepherding\":[\"I care about walking alongside people over time as they grow.\",\"I have faithfully supported and guided others in their journey.\"],\n \"Evangelism & Follow-Up\":[\"I love connecting with newcomers and helping them take a next step.\",\"I have helped new or unconnected people become settled and connected.\"]\n};\nconst ROLEMAP={\"Welcome Usher\":[\"Hospitality\",\"Encouragement\"],\"Floor / Head-Usher track\":[\"Administration\",\"Leadership\"],\n \"Ministry Support (Catcher) / Safety\":[\"Faith\",\"Discernment\",\"Mercy\",\"Helps & Service\"],\n \"Follow-Up Usher\":[\"Evangelism & Follow-Up\",\"Shepherding\"],\"Undergirding support (any role)\":[\"Giving\",\"Intercession\"]};\nlet ITEMS=[];\nObject.keys(GIFTS).forEach((g,gi)=>{ITEMS.push({g,axis:\"P\",t:GIFTS[g][0],k:\"g\"+gi+\"P\"});ITEMS.push({g,axis:\"E\",t:GIFTS[g][1],k:\"g\"+gi+\"E\"});});\nITEMS=ITEMS.map((it,i)=>({...it,o:(i*13+4)%ITEMS.length})).sort((a,b)=>a.o-b.o);\nconst SKEY=\"grc_usher_p3_\"+CID, ans=JSON.parse(localStorage.getItem(SKEY)||\"{}\");\nconst form=document.getElementById(\"form\");\nITEMS.forEach(it=>{\n  const q=document.createElement(\"div\");q.className=\"q\";\n  q.innerHTML='<div class=\"tag\">'+(it.axis===\"P\"?\"What I love\":\"What has shown up\")+'</div><div class=\"stmt\">'+it.t+'</div><div class=\"i-scale\">'+\n    [1,2,3,4,5].map(v=>'<label><input type=\"radio\" name=\"'+it.k+'\" value=\"'+v+'\"><span class=\"num\">'+v+'</span></label>').join('')+'</div>';\n  form.appendChild(q);\n  if(ans[it.k]){const r=q.querySelector('input[value=\"'+ans[it.k]+'\"]');if(r){r.checked=true;r.closest('label').classList.add('sel');}}\n});\nfunction refresh(){const done=Object.keys(ans).length;\n  document.getElementById(\"prog\").textContent=done+\" of \"+ITEMS.length;\n  document.getElementById(\"fill\").style.width=(done/ITEMS.length*100)+\"%\";\n  document.getElementById(\"submit\").disabled=done<ITEMS.length;}\nform.addEventListener(\"change\",e=>{if(e.target.name){ans[e.target.name]=+e.target.value;localStorage.setItem(SKEY,JSON.stringify(ans));\n  e.target.closest(\".i-scale\").querySelectorAll(\"label\").forEach(l=>l.classList.remove(\"sel\"));\n  e.target.closest(\"label\").classList.add(\"sel\");refresh();}});\nrefresh();\ndocument.getElementById(\"submit\").addEventListener(\"click\",async()=>{\n  const res={};Object.keys(GIFTS).forEach((g,gi)=>{const P=ans[\"g\"+gi+\"P\"]||0,E=ans[\"g\"+gi+\"E\"]||0;\n    let quad=P>=4&&E>=4?\"Confirmed\":P>=4?\"Emerging\":E>=4?\"Latent\":\"Not primary\";res[g]={P,E,total:(P+E)*2,quad};});\n  const top=Object.keys(res).sort((a,b)=>res[b].total-res[a].total).slice(0,5);\n  let bestRole=\"\",bestAvg=-1;\n  Object.keys(ROLEMAP).forEach(r=>{const gs=ROLEMAP[r];const avg=gs.reduce((s,g)=>s+res[g].total,0)/gs.length;if(avg>bestAvg){bestAvg=avg;bestRole=r;}});\n  let rows=top.map(g=>'<div class=\"gift\"><span>'+g+'</span><span><b>'+res[g].total+'/20</b> · '+res[g].quad+'</span></div>').join('');\n  document.getElementById(\"result\").innerHTML='<div class=\"result\"><h2>Your top serving gifts</h2>'+rows+\n    '<div class=\"role\"><b>Best-fit usher role:</b><br>'+bestRole+'</div>'+\n    '<div style=\"margin-top:18px;padding:20px 16px;border-radius:14px;background:linear-gradient(135deg,#EEF8F0,#EAF1EE);border:1.5px solid #CDE7D6;text-align:center\">'+\n      '<div style=\"font-size:2rem;line-height:1\">&#128591;</div>'+\n      '<div style=\"font-weight:800;color:var(--tdkr);font-size:1.1rem;margin-top:6px\">Thank you &mdash; all done!</div>'+\n      '<p style=\"color:var(--blk);font-size:.88rem;margin-top:10px;line-height:1.6\">Thank you very much for your interest and for completing your Usher &amp; Catcher Serve Readiness Profile. Your responses have been received in full. Your Head Usher will receive your results and be in touch with you shortly. You can view your full report now using the button below.</p>'+\n      '<a class=\"btn-sb\" style=\"display:block;text-align:center;text-decoration:none;line-height:1.2;margin-top:14px\" href=\"/report/'+CID+'\">View my full report</a>'+\n      '<div style=\"font-size:.78rem;color:var(--gry);margin-top:14px\">Gateway Revival Church &mdash; Benoni</div>'+\n    '</div></div>';\n  document.getElementById(\"result\").scrollIntoView({behavior:\"smooth\"});\n  /* Closeout rendered synchronously above — never depends on this call. */\n  try{const rr=await fetch(\"/section-submit\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},\n    body:JSON.stringify({course:\"usher\",section:\"u3\",contactId:CID,gifts:res,top:top,role_fit:bestRole})});\n    const dd=await rr.json();if(dd&&dd.home)document.getElementById(\"result\").insertAdjacentHTML(\"beforeend\",'<div class=\"nav\"><a href=\"'+dd.home+'\" style=\"display:block;text-align:center;color:var(--tdk);font-weight:700;font-size:.85rem;text-decoration:none\">Return to GRC home</a></div>');}catch(e){}\n});\n</script>\n</body>\n</html>\n","register.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>GRC Serve | Usher &amp; Catcher Registration</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  *{margin:0;padding:0;box-sizing:border-box}\n  :root{--blk:#231F20;--gry:#6B6B6B;--glt:#F5F5F5;--wht:#FFFFFF;--tdk:#547878;--tdkr:#3B6261;--t2:#7DA3A4;--fn:'Montserrat',sans-serif;--rd:14px;--sh:0 4px 28px rgba(84,120,120,.12)}\n  html{font-family:var(--fn);color:var(--blk);-webkit-tap-highlight-color:transparent}\n  body{min-height:100vh;background:linear-gradient(160deg,#EEF5F8 0%,#EBF4F4 50%,#EAF1EE 100%)}\n  .app{max-width:560px;margin:0 auto;padding:14px 10px 60px}\n  .card{background:var(--wht);border-radius:var(--rd);box-shadow:var(--sh);overflow:hidden;margin-bottom:12px}\n  .top-hdr{padding:22px 18px 16px;text-align:center;border-bottom:2px solid #EEF5F8}\n  .top-hdr h1{font-size:1.05rem;font-weight:800;color:var(--tdkr)}\n  .sec-badge{display:inline-block;margin-top:10px;background:linear-gradient(135deg,var(--tdk),var(--t2));color:var(--wht);font-size:.67rem;font-weight:700;padding:5px 15px;border-radius:20px;letter-spacing:.8px;text-transform:uppercase}\n  .hdr-sub{font-size:.78rem;color:var(--gry);margin-top:10px;line-height:1.55;padding:0 6px}\n  .body{padding:18px}\n  label.fld{display:block;font-size:.72rem;font-weight:700;color:var(--gry);margin:14px 0 5px;text-transform:uppercase;letter-spacing:.4px}\n  input[type=text],input[type=tel],input[type=email]{width:100%;padding:13px 14px;border:1.5px solid #E3EBEC;border-radius:10px;font-family:var(--fn);font-size:.95rem}\n  input:focus{outline:none;border-color:var(--tdk)}\n  .selfie{margin-top:8px;text-align:center}\n  .selfie video,.selfie img{width:180px;height:180px;object-fit:cover;border-radius:50%;border:3px solid var(--tdk);background:#e8eeef}\n  .selfie .row{display:flex;gap:8px;justify-content:center;margin-top:10px;flex-wrap:wrap}\n  .mini{padding:9px 16px;border-radius:9px;border:1.5px solid var(--tdk);background:var(--wht);color:var(--tdk);font-weight:700;font-size:.78rem;cursor:pointer;font-family:var(--fn)}\n  .mini.solid{background:var(--tdk);color:var(--wht)}\n  .btn-sb{width:100%;margin-top:20px;padding:15px 20px;border-radius:10px;font-size:.92rem;font-weight:700;border:none;cursor:pointer;font-family:var(--fn);background:linear-gradient(135deg,var(--blk),var(--tdkr));color:var(--wht);box-shadow:0 3px 13px rgba(59,98,97,.32)}\n  .btn-sb:disabled{opacity:.45;box-shadow:none}\n  .hint{font-size:.68rem;color:var(--gry);margin-top:6px;text-align:center}\n  .foot{text-align:center;color:var(--gry);font-size:.68rem;padding:14px 0 4px}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <div class=\"card\">\n    <div class=\"top-hdr\">\n      <h1>Gateway Revival Church</h1>\n      <div class=\"sec-badge\">Usher &amp; Catcher Registration</div>\n      <div class=\"hdr-sub\">Welcome! Register below to begin your Serve Readiness Profile. Your selfie helps your Head Usher recognise you on the team.</div>\n    </div>\n    <div class=\"body\">\n      <label class=\"fld\">Full name</label>\n      <input type=\"text\" id=\"name\" autocomplete=\"name\" placeholder=\"Name and surname\">\n      <label class=\"fld\">Mobile number</label>\n      <input type=\"tel\" id=\"mobile\" autocomplete=\"tel\" placeholder=\"e.g. 082 123 4567\">\n      <label class=\"fld\">Email</label>\n      <input type=\"email\" id=\"email\" autocomplete=\"email\" placeholder=\"you@example.com\">\n\n      <label class=\"fld\">Your selfie</label>\n      <div class=\"selfie\">\n        <video id=\"cam\" autoplay playsinline muted style=\"display:none\"></video>\n        <img id=\"shot\" alt=\"selfie preview\" style=\"display:none\">\n        <div id=\"ph\" style=\"width:180px;height:180px;border-radius:50%;border:3px dashed #B7C7C9;display:flex;align-items:center;justify-content:center;color:var(--gry);font-size:.72rem;margin:0 auto\">No photo yet</div>\n        <div class=\"row\">\n          <button type=\"button\" class=\"mini solid\" id=\"start\">Open camera</button>\n          <button type=\"button\" class=\"mini\" id=\"snap\" style=\"display:none\">Capture</button>\n          <button type=\"button\" class=\"mini\" id=\"retake\" style=\"display:none\">Retake</button>\n        </div>\n        <input type=\"file\" id=\"file\" accept=\"image/*\" capture=\"user\" style=\"display:none\">\n        <div class=\"hint\">Camera not working? <a href=\"#\" id=\"pick\" style=\"color:var(--tdk)\">upload a photo</a> instead.</div>\n      </div>\n\n      <button class=\"btn-sb\" id=\"go\" disabled>Start my assessment</button>\n      <div class=\"hint\" id=\"status\"></div>\n    </div>\n  </div>\n  <div class=\"foot\">Gateway Revival Church — Benoni · Ministry Training</div>\n</div>\n<canvas id=\"cv\" width=\"480\" height=\"480\" style=\"display:none\"></canvas>\n<script>\nconst $=id=>document.getElementById(id);\nlet selfie=\"\";let stream=null;\nfunction validate(){const ok=$(\"name\").value.trim()&&$(\"email\").value.trim()&&$(\"mobile\").value.trim()&&selfie;$(\"go\").disabled=!ok;}\n[\"name\",\"mobile\",\"email\"].forEach(id=>$(id).addEventListener(\"input\",validate));\n$(\"start\").addEventListener(\"click\",async()=>{\n  try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:\"user\"}});\n    $(\"cam\").srcObject=stream;$(\"cam\").style.display=\"block\";$(\"ph\").style.display=\"none\";$(\"shot\").style.display=\"none\";\n    $(\"start\").style.display=\"none\";$(\"snap\").style.display=\"inline-block\";\n  }catch(e){$(\"file\").click();}\n});\n$(\"snap\").addEventListener(\"click\",()=>{\n  const c=$(\"cv\"),v=$(\"cam\");const s=Math.min(v.videoWidth,v.videoHeight);\n  c.getContext(\"2d\").drawImage(v,(v.videoWidth-s)/2,(v.videoHeight-s)/2,s,s,0,0,480,480);\n  selfie=c.toDataURL(\"image/jpeg\",0.82);\n  $(\"shot\").src=selfie;$(\"shot\").style.display=\"block\";$(\"cam\").style.display=\"none\";\n  $(\"snap\").style.display=\"none\";$(\"retake\").style.display=\"inline-block\";\n  if(stream){stream.getTracks().forEach(t=>t.stop());}validate();\n});\n$(\"retake\").addEventListener(\"click\",()=>{selfie=\"\";$(\"shot\").style.display=\"none\";$(\"retake\").style.display=\"none\";$(\"start\").style.display=\"inline-block\";$(\"ph\").style.display=\"flex\";validate();});\n$(\"pick\").addEventListener(\"click\",e=>{e.preventDefault();$(\"file\").click();});\n$(\"file\").addEventListener(\"change\",e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();\n  r.onload=()=>{const img=new Image();img.onload=()=>{const c=$(\"cv\");const s=Math.min(img.width,img.height);\n    c.getContext(\"2d\").drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,480,480);selfie=c.toDataURL(\"image/jpeg\",0.82);\n    $(\"shot\").src=selfie;$(\"shot\").style.display=\"block\";$(\"ph\").style.display=\"none\";$(\"start\").style.display=\"none\";$(\"retake\").style.display=\"inline-block\";validate();};img.src=r.result;};\n  r.readAsDataURL(f);});\n$(\"go\").addEventListener(\"click\",async()=>{\n  $(\"go\").disabled=true;$(\"status\").textContent=\"Setting up your profile…\";\n  const payload={course:\"usher\",name:$(\"name\").value.trim(),mobile:$(\"mobile\").value.trim(),email:$(\"email\").value.trim().toLowerCase(),selfie:selfie};\n  try{\n    const r=await fetch(\"/register\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify(payload)});\n    const d=await r.json();\n    if(d&&d.contactId){location.href=\"/u1/\"+d.contactId;return;}\n    $(\"status\").textContent=\"Registered — continue to Part 1.\";location.href=\"/u1\";\n  }catch(e){$(\"status\").textContent=\"Could not reach the server. Please try again.\";$(\"go\").disabled=false;}\n});\n</script>\n</body>\n</html>\n","candidate_report.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>GRC Serve — Your Readiness Profile</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  /* Report template — placeholders {{...}} filled by the report generator.\n     Reuses the GRC design tokens; print-friendly (A4). */\n  *{margin:0;padding:0;box-sizing:border-box}\n  :root{--blk:#231F20;--gry:#6B6B6B;--glt:#F5F5F5;--wht:#fff;--tdk:#547878;--tdkr:#3B6261;--t2:#7DA3A4;--gold:#C8900A;--fn:'Montserrat',sans-serif}\n  body{font-family:var(--fn);color:var(--blk);background:#EEF3F4;padding:16px}\n  .pg{max-width:720px;margin:0 auto;background:var(--wht);border-radius:16px;overflow:hidden;box-shadow:0 4px 28px rgba(84,120,120,.14)}\n  .hero{background:linear-gradient(135deg,var(--tdk),var(--tdkr));color:#fff;padding:26px 24px;text-align:center}\n  .hero img{width:104px;height:104px;border-radius:50%;object-fit:cover;border:3px solid rgba(255,255,255,.7);margin-bottom:12px}\n  .hero h1{font-size:1.3rem;font-weight:800}\n  .hero .sub{opacity:.9;font-size:.8rem;margin-top:4px}\n  .sec{padding:20px 24px;border-bottom:1px solid #EEF3F4}\n  .sec h2{font-size:.72rem;text-transform:uppercase;letter-spacing:.8px;color:var(--tdk);font-weight:800;margin-bottom:10px}\n  .big{font-size:1.8rem;font-weight:800;color:var(--tdkr)}\n  .row{display:flex;justify-content:space-between;padding:6px 0;font-size:.9rem;border-top:1px solid #F1F5F6}\n  .role{background:var(--glt);border-radius:12px;padding:16px;font-size:.95rem}\n  .role b{color:var(--tdkr)}\n  .verse{font-style:italic;color:var(--gry);font-size:.88rem;text-align:center;padding:20px 24px}\n  .foot{text-align:center;color:var(--gry);font-size:.7rem;padding:14px}\n  .actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;padding:18px 24px;background:#F7FAFA;border-top:1px solid #EEF3F4}\n  .actions button,.actions a{font-family:var(--fn);cursor:pointer;border:none;border-radius:10px;padding:13px 20px;font-size:.85rem;font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:7px;box-shadow:0 3px 12px rgba(59,98,97,.22)}\n  .btn-pdf{background:linear-gradient(135deg,var(--tdk),var(--tdkr));color:#fff}\n  .btn-wa{background:#25D366;color:#fff}\n  @media print{.actions{display:none!important}body{background:#fff;padding:0}.pg{box-shadow:none;border-radius:0;max-width:100%}}\n</style>\n</head>\n<body>\n<div class=\"pg\">\n  <div class=\"hero\">\n    <img src=\"{{selfie_url}}\" alt=\"{{name}}\">\n    <h1>{{name}}</h1>\n    <div class=\"sub\">Your GRC Serve Readiness Profile · {{date}}</div>\n  </div>\n\n  <div class=\"sec\">\n    <h2>Part 1 · Servant Heart Profile</h2>\n    <div class=\"big\">{{s1_code}}</div>\n    <p style=\"margin-top:4px\"><b>{{s1_primary}}</b> (primary) · <b>{{s1_secondary}}</b> (secondary)</p>\n    <p style=\"margin-top:8px;font-size:.92rem\">{{s1_how_you_serve}}</p>\n  </div>\n\n  <div class=\"sec\">\n    <h2>Part 2 · Serve-Ready Check</h2>\n    <div class=\"big\">{{s2_band}}</div>\n    <p style=\"margin-top:2px\">Readiness score: <b>{{s2_score}}/100</b></p>\n    <p style=\"margin-top:8px;font-size:.9rem\">{{s2_encouragement}}</p>\n  </div>\n\n  <div class=\"sec\">\n    <h2>Part 3 · Your Top Serving Gifts</h2>\n    {{s3_top_gifts_rows}}\n  </div>\n\n  <div class=\"sec\">\n    <div class=\"role\">\n      <b>Your best-fit serving role:</b><br>{{role_fit}}<br>\n      <span style=\"font-size:.85rem;color:var(--gry)\">{{role_fit_note}}</span>\n    </div>\n  </div>\n\n  <div class=\"actions\">\n    <button type=\"button\" class=\"btn-pdf\" onclick=\"window.print()\">&#128190; Save / Print as PDF</button>\n    <a id=\"wa\" class=\"btn-wa\" href=\"#\" target=\"_blank\" rel=\"noopener\">&#128241; Send to WhatsApp</a>\n  </div>\n\n  <div class=\"verse\">\n    \"Each of you should use whatever gift you have received to serve others, as faithful stewards of God's grace in its various forms.\" — 1 Peter 4:10\n    <div style=\"margin-top:10px;font-style:normal\">Your Head Usher will be in touch about your next step.<br><b>Gateway Revival Church — Benoni</b></div>\n  </div>\n  <div class=\"foot\">GRC Ministry Training · Usher &amp; Catcher · Serve Readiness Profile</div>\n</div>\n<script>\n  (function(){var u=location.href.split('#')[0];\n   var msg=\"My Gateway Revival Church — Usher & Catcher Serve Readiness report:\\n\"+u;\n   var wa=document.getElementById(\"wa\");if(wa)wa.href=\"https://wa.me/?text=\"+encodeURIComponent(msg);})();\n</script>\n</body>\n</html>\n","pastoral_report.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>GRC Serve — Pastoral Review (Confidential)</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n  /* Pastoral report — CONFIDENTIAL. Placeholders {{...}} filled by generator. */\n  *{margin:0;padding:0;box-sizing:border-box}\n  :root{--blk:#231F20;--gry:#6B6B6B;--glt:#F5F5F5;--wht:#fff;--tdk:#547878;--tdkr:#3B6261;--warn:#a3400f;--fn:'Montserrat',sans-serif}\n  body{font-family:var(--fn);color:var(--blk);background:#EEF3F4;padding:16px}\n  .pg{max-width:720px;margin:0 auto;background:var(--wht);border-radius:16px;overflow:hidden;box-shadow:0 4px 28px rgba(84,120,120,.14)}\n  .hero{background:var(--blk);color:#fff;padding:22px 24px;display:flex;align-items:center;gap:16px}\n  .hero img{width:76px;height:76px;border-radius:50%;object-fit:cover;border:2px solid rgba(255,255,255,.5)}\n  .hero h1{font-size:1.1rem;font-weight:800}\n  .hero .sub{opacity:.85;font-size:.72rem;margin-top:3px}\n  .conf{background:var(--warn);color:#fff;font-size:.62rem;font-weight:800;text-transform:uppercase;letter-spacing:.8px;text-align:center;padding:6px}\n  .sec{padding:18px 24px;border-bottom:1px solid #EEF3F4}\n  .sec h2{font-size:.7rem;text-transform:uppercase;letter-spacing:.8px;color:var(--tdk);font-weight:800;margin-bottom:10px}\n  .row{display:flex;justify-content:space-between;padding:6px 0;font-size:.86rem;border-top:1px solid #F1F5F6}\n  .flag{background:#FFF3EC;border:1px solid #F0C9AE;border-radius:10px;padding:12px;color:var(--warn);font-size:.85rem;font-weight:600;margin-top:10px}\n  .action{background:var(--glt);border-radius:10px;padding:14px;font-size:.9rem;margin-top:8px}\n  .action b{color:var(--tdkr)}\n  .foot{text-align:center;color:var(--gry);font-size:.68rem;padding:14px}\n  .actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;padding:18px 24px;background:#F7FAFA;border-top:1px solid #EEF3F4}\n  .actions button,.actions a{font-family:var(--fn);cursor:pointer;border:none;border-radius:10px;padding:13px 20px;font-size:.85rem;font-weight:700;text-decoration:none;display:inline-flex;align-items:center;gap:7px;box-shadow:0 3px 12px rgba(59,98,97,.22)}\n  .btn-pdf{background:linear-gradient(135deg,var(--tdk),var(--tdkr));color:#fff}\n  .btn-wa{background:#25D366;color:#fff}\n  .actions .note{flex-basis:100%;text-align:center;font-size:.68rem;color:var(--warn);margin-top:2px}\n  @media print{.actions{display:none!important}body{background:#fff;padding:0}.pg{box-shadow:none;border-radius:0;max-width:100%}}\n</style>\n</head>\n<body>\n<div class=\"pg\">\n  <div class=\"conf\">Confidential — For Pastoral / Head-Usher Review Only</div>\n  <div class=\"hero\">\n    <img src=\"{{selfie_url}}\" alt=\"{{name}}\">\n    <div><h1>{{name}}</h1><div class=\"sub\">{{mobile}} · {{email}} · {{date}}</div></div>\n  </div>\n\n  <div class=\"sec\">\n    <h2>Part 1 · Servant Heart Profile</h2>\n    <div class=\"row\"><span>Profile code</span><span><b>{{s1_code}}</b> — {{s1_primary}}/{{s1_secondary}}</span></div>\n    <div class=\"row\"><span>Trait totals</span><span>{{s1_trait_totals}}</span></div>\n    <div class=\"row\"><span>Temperament role-lean</span><span>{{s1_role_lean}}</span></div>\n  </div>\n\n  <div class=\"sec\">\n    <h2>Part 2 · Serve-Ready Check</h2>\n    <div class=\"row\"><span>Readiness</span><span><b>{{s2_band}}</b> · {{s2_score}}/100</span></div>\n    {{s2_domain_rows}}\n    {{s2_pastoral_flag_block}}\n  </div>\n\n  <div class=\"sec\">\n    <h2>Part 3 · Ministry Fit &amp; Gifting</h2>\n    {{s3_gift_rows}}\n    <div class=\"row\"><span>Best-fit usher role</span><span><b>{{role_fit}}</b></span></div>\n  </div>\n\n  <div class=\"sec\">\n    <h2>Recommended Action</h2>\n    <div class=\"action\">\n      <b>Placement:</b> {{recommended_role}}<br>\n      <b>Pastoral action:</b> {{pastoral_action}}\n    </div>\n  </div>\n  <div class=\"actions\">\n    <button type=\"button\" class=\"btn-pdf\" onclick=\"window.print()\">&#128190; Save / Print as PDF</button>\n    <a id=\"wa\" class=\"btn-wa\" href=\"#\" target=\"_blank\" rel=\"noopener\">&#128241; Send to WhatsApp</a>\n    <div class=\"note\">Confidential — share only with pastoral / Head-Usher leadership.</div>\n  </div>\n  <div class=\"foot\">GRC Ministry Training · Usher &amp; Catcher · Pastoral Review · Do Not Distribute</div>\n</div>\n<script>\n  (function(){var u=location.href.split('#')[0];\n   var msg=\"CONFIDENTIAL — GRC Usher & Catcher pastoral report ({{name}}):\\n\"+u;\n   var wa=document.getElementById(\"wa\");if(wa)wa.href=\"https://wa.me/?text=\"+encodeURIComponent(msg);})();\n</script>\n</body>\n</html>\n"};
// Bundled worker logic — pages are injected as a global 'const PAGES = {...}'
// (filename -> HTML string) prepended at build time. Same routes as worker.js
// but self-contained (no ASSETS binding), so it deploys as a single module.
const SECTIONS = { u1: "u1.html", u2: "u2.html", u3: "u3.html" };
const ROLE_LEAN = { EX: "Welcome Usher", DR: "Floor / Head-Usher track", DE: "Ministry Support / Safety", ST: "Ministry Support (Catcher) & Follow-Up" };
const ROLE_TAG = { "Welcome Usher": "usher-role-welcome", "Floor / Head-Usher track": "usher-role-floor", "Ministry Support (Catcher) / Safety": "usher-role-ministry-support", "Follow-Up Usher": "usher-role-followup", "Undergirding support (any role)": "" };
const GHL_BASE = "https://services.leadconnectorhq.com";
const SUMMARY_FIELD_ID = "Y9fbY2JOAdxPagXxmtVB"; // the "usher_*" contact field

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const p = url.pathname;
    try {
      let m = p.match(/^\/u\/([A-Za-z0-9]+)\/?$/);
      if (m) return Response.redirect(url.origin + "/u1/" + m[1], 302);

      m = p.match(/^\/(u1|u2|u3)(\/.*)?$/);
      if (m) return html(PAGES[SECTIONS[m[1]]]);

      if (p === "/register" && request.method === "GET") return html(PAGES["register.html"]);

      if (p === "/register" && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        if (!b || !b.email || !b.name) return json({ ok: false, error: "bad_payload" }, 400);
        let contactId = null;
        if (env.GHL_API_TOKEN && env.GHL_LOCATION_ID) {
          try {
            const up = await fetch("https://services.leadconnectorhq.com/contacts/upsert", {
              method: "POST",
              headers: { Authorization: "Bearer " + env.GHL_API_TOKEN, Version: "2021-07-28", "Content-Type": "application/json" },
              body: JSON.stringify({ locationId: env.GHL_LOCATION_ID, name: b.name, email: b.email, phone: b.mobile, tags: ["usher-registered", "usher-selfie-captured"] })
            });
            const uj = await up.json();
            contactId = (uj.contact && uj.contact.id) || uj.id || null;
          } catch (e) {}
        }
        if (b.selfie && env.R2) {
          try {
            const key = "grc-usher-photos/" + (contactId || b.email.replace(/[^a-z0-9]/gi, "_")) + ".jpg";
            const bin = Uint8Array.from(atob(String(b.selfie).split(",").pop()), c => c.charCodeAt(0));
            await env.R2.put(key, bin, { httpMetadata: { contentType: "image/jpeg" } });
          } catch (e) {}
        }
        return json({ ok: true, contactId });
      }

      if (p === "/section-submit" && request.method === "POST") {
        const b = await request.json().catch(() => ({}));
        if (!b || b.course !== "usher" || !SECTIONS[b.section]) return json({ ok: false, error: "bad_payload" }, 400);
        const cid = String(b.contactId || "").replace(/[^A-Za-z0-9]/g, "") || null;
        await env.DB.prepare("INSERT INTO usher_submission (contact_id, section, payload, created_at) VALUES (?1,?2,?3,?4)")
          .bind(cid, b.section, JSON.stringify(b), Date.now()).run();
        // Carry through to GHL (never blocks the save — D1 is source of truth).
        if (env.GHL_API_TOKEN && cid) {
          try {
            await ghlAddTags(env, cid, ["usher-" + b.section + "-complete"]);
            const secs = await env.DB.prepare("SELECT DISTINCT section FROM usher_submission WHERE contact_id=?1").bind(cid).all();
            const have = new Set((secs.results || []).map(r => r.section));
            if (have.has("u1") && have.has("u2") && have.has("u3")) {
              const u3 = await latest(env, cid, "u3");
              const roleTag = u3 && ROLE_TAG[u3.role_fit] ? [ROLE_TAG[u3.role_fit]] : [];
              await ghlAddTags(env, cid, ["usher-cleared"].concat(roleTag));
              await ghlWriteSummary(env, cid);
              // Email the candidate their report — exactly once — so delivery does
              // not depend on a GHL workflow being built. Guarded by a marker row.
              const already = await env.DB.prepare("SELECT 1 AS x FROM usher_submission WHERE contact_id=?1 AND section='_emailed' LIMIT 1").bind(cid).first();
              if (!already) {
                const sent = await ghlSendCandidateEmail(env, cid, url.origin);
                if (sent) await env.DB.prepare("INSERT INTO usher_submission (contact_id, section, payload, created_at) VALUES (?1,'_emailed','{}',?2)").bind(cid, Date.now()).run();
              }
            }
          } catch (e) {}
        }
        return json({ ok: true, home: env.HOME_URL || null });
      }

      m = p.match(/^\/report\/([A-Za-z0-9]+)\/?$/);
      if (m) return renderReport(env, m[1], "candidate");

      // Friendly guard: /report opened without a valid contact id (e.g. an
      // unresolved {{contact.id}} merge field from a funnel button) — never
      // show the raw JSON 404 to a candidate.
      if (p === "/report" || p.startsWith("/report/") || p.startsWith("/report%")) {
        return html("<body style='font-family:sans-serif;padding:40px 24px;text-align:center;color:#231F20'><div style='max-width:420px;margin:0 auto'><h2 style='color:#3B6261'>Your report link needs your personal ID</h2><p style='color:#6B6B6B;line-height:1.6'>Please open your report from the button at the end of your assessment, or from the personal link sent to you. If you have not completed all three parts yet, finish them first and your report will be ready.</p></div></body>", 404);
      }

      m = p.match(/^\/pastoral\/([A-Za-z0-9]+)\/?$/);
      if (m) {
        if (!env.PASTORAL_TOKEN || url.searchParams.get("token") !== env.PASTORAL_TOKEN)
          return html("<body style='font-family:sans-serif;padding:32px;text-align:center'><h2>Confidential pastoral report</h2><p>This link requires authorised access.</p></body>", 403);
        return renderReport(env, m[1], "pastoral");
      }

      if (p === "/health") {
        let db = "x";
        try { const r = await env.DB.prepare("SELECT COUNT(*) n FROM usher_submission").first(); db = "ok:" + r.n; }
        catch (e) { db = "err:" + (e && e.message || e); }
        return json({ ok: true, worker: "grc-usher-staging-worker", environment: env.ENVIRONMENT, db });
      }

      return json({ error: "not_found", routes: ["/u/<cid>", "/u1|u2|u3/<cid>", "/register", "POST /section-submit", "/report/<cid>", "/pastoral/<cid>?token=", "/health"] }, 404);
    } catch (e) {
      return json({ error: "worker_exception", message: String(e && e.message || e) }, 500);
    }
  }
};

async function latest(env, cid, section) {
  const r = await env.DB.prepare("SELECT payload FROM usher_submission WHERE contact_id=?1 AND section=?2 ORDER BY created_at DESC LIMIT 1").bind(cid, section).first();
  if (!r) return null;
  try { return JSON.parse(r.payload); } catch (e) { return null; }
}

async function renderReport(env, cid, kind) {
  const [u1, u2, u3] = await Promise.all([latest(env, cid, "u1"), latest(env, cid, "u2"), latest(env, cid, "u3")]);
  if (!u1 && !u2 && !u3) return html("<body style='font-family:sans-serif;padding:32px;text-align:center'><h2>Report not ready</h2><p>This profile has not completed the assessment yet.</p></body>", 404);
  const tpl = PAGES[kind === "pastoral" ? "pastoral_report.html" : "candidate_report.html"];
  let selfie = (env.R2_PUBLIC_BASE || "") + "/grc-usher-photos/" + cid + ".jpg";
  let name = "", mobile = "", email = "";
  if (env.GHL_API_TOKEN) {
    try {
      const r = await fetch(GHL_BASE + "/contacts/" + cid, { headers: ghlHeaders(env) });
      if (r.ok) {
        const c = (await r.json()).contact || {};
        name = c.contactName || ((c.firstName || "") + " " + (c.lastName || "")).trim();
        mobile = c.phone || ""; email = c.email || "";
        if (Array.isArray(c.customFields)) {
          const pf = c.customFields.find(function (f) { return /photo|selfie/i.test(String(f.value || "")) && /^https?:/.test(String(f.value || "")); });
          if (pf) selfie = pf.value;
        }
      }
    } catch (e) {}
  }
  const V = {
    name: name, mobile: mobile, email: email, date: new Date().toISOString().slice(0, 10), selfie_url: selfie,
    s1_code: u1 ? u1.code : "—", s1_primary: u1 ? u1.primary : "", s1_secondary: u1 ? u1.secondary : "",
    s1_how_you_serve: u1 ? servingLine(u1.primary) : "", s1_role_lean: u1 ? ROLE_LEAN[u1.primary] : "",
    s1_trait_totals: u1 ? Object.entries(u1.scores).map(function (e) { return e[0] + ":" + e[1]; }).join("  ") : "",
    s2_band: u2 ? u2.band : "—", s2_score: u2 ? u2.normalised : "—", s2_encouragement: u2 ? bandNote(u2.band) : "",
    s2_domain_rows: u2 ? Object.entries(u2.domains).map(function (e) { return row(e[0], Math.round(e[1] / 25 * 100) + "%"); }).join("") : "",
    s2_pastoral_flag_block: (u2 && u2.pastoral_flag) ? "<div class='flag'>Pastoral flag: conversation recommended before active service.</div>" : "",
    s3_top_gifts_rows: u3 ? u3.top.map(function (g) { return row(g, u3.gifts[g].total + "/20 · " + u3.gifts[g].quad); }).join("") : "",
    s3_gift_rows: u3 ? u3.top.map(function (g) { return row(g, u3.gifts[g].total + "/20 · " + u3.gifts[g].quad); }).join("") : "",
    role_fit: u3 ? u3.role_fit : (u1 ? ROLE_LEAN[u1.primary] : "—"),
    role_fit_note: "Confirmed by your temperament (Part 1) and gifts (Part 3).",
    recommended_role: u3 ? u3.role_fit : "", pastoral_action: (u2 && u2.pastoral_flag) ? "Conversation required before placement." : "Cleared for role induction."
  };
  return html(tpl.replace(/\{\{(\w+)\}\}/g, function (_, k) { return (k in V ? String(V[k]) : ""); }));
}

function row(a, b) { return "<div class='row'><span>" + a + "</span><span>" + b + "</span></div>"; }
function servingLine(p) { return ({ EX: "You serve best where people are met and made to feel welcome.", DR: "You serve best where someone must take charge and keep things moving.", DE: "You serve best where attentiveness and care for detail protect people.", ST: "You serve best where steady, dependable, behind-the-scenes care is needed." })[p] || ""; }
function bandNote(b) { return b === "Ready" ? "You show strong, consistent readiness to serve." : b === "Developing" ? "You are growing well — a few areas will strengthen with support." : "Some areas need growth before active service; your pastor will walk with you."; }
function json(o, s) { return new Response(JSON.stringify(o, null, 2), { status: s || 200, headers: { "content-type": "application/json", "cache-control": "no-store" } }); }
function html(h, s) { return new Response(h, { status: s || 200, headers: { "content-type": "text/html;charset=utf-8", "cache-control": "no-store" } }); }

// ── GHL write-through helpers ────────────────────────────────────────────────
function ghlHeaders(env) { return { Authorization: "Bearer " + env.GHL_API_TOKEN, Version: "2021-07-28", "Content-Type": "application/json" }; }
async function ghlAddTags(env, cid, tags) {
  await fetch(GHL_BASE + "/contacts/" + cid + "/tags", { method: "POST", headers: ghlHeaders(env), body: JSON.stringify({ tags: tags }) });
}
function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
async function ghlSendCandidateEmail(env, cid, origin) {
  if (!env.GHL_API_TOKEN) return false;
  try {
    const r = await fetch(GHL_BASE + "/contacts/" + cid, { headers: ghlHeaders(env) });
    if (!r.ok) return false;
    const c = (await r.json()).contact || {};
    if (!c.email) return false;
    const first = c.firstName || "there";
    const link = origin + "/report/" + cid;
    const body = "<div style='font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#231F20;line-height:1.6;max-width:520px'>"
      + "<p>Dear " + esc(first) + ",</p>"
      + "<p>Thank you for completing your Usher &amp; Catcher Serve Readiness Profile. Your full report is ready.</p>"
      + "<p style='margin:22px 0'><a href='" + link + "' style='background:#3B6261;color:#ffffff;padding:13px 24px;border-radius:8px;text-decoration:none;font-weight:bold;display:inline-block'>View My Report</a></p>"
      + "<p style='font-size:13px;color:#6B6B6B'>Or open this link:<br><a href='" + link + "' style='color:#3B6261'>" + link + "</a></p>"
      + "<p>Your Head Usher will also be in touch with you shortly about your next steps in serving.</p>"
      + "<p>Love &amp; blessings,<br><b>Gateway Revival Church — Benoni</b></p></div>";
    const resp = await fetch(GHL_BASE + "/conversations/messages", {
      method: "POST", headers: ghlHeaders(env),
      body: JSON.stringify({ type: "Email", contactId: cid, subject: "Your Gateway Revival Church — Usher & Catcher Report", html: body })
    });
    return resp.ok;
  } catch (e) { return false; }
}
async function ghlWriteSummary(env, cid) {
  const [u1, u2, u3] = await Promise.all([latest(env, cid, "u1"), latest(env, cid, "u2"), latest(env, cid, "u3")]);
  const parts = [];
  if (u1) parts.push("S1 " + u1.code);
  if (u2) parts.push("S2 " + u2.band + " " + u2.normalised + "/100");
  if (u3) parts.push("S3 " + (u3.role_fit || "") + " [" + (u3.top || []).slice(0, 3).join(", ") + "]");
  const summary = "Usher assessment complete — " + parts.join(" | ");
  await fetch(GHL_BASE + "/contacts/" + cid, { method: "PUT", headers: ghlHeaders(env), body: JSON.stringify({ customFields: [{ id: SUMMARY_FIELD_ID, field_value: summary }] }) });
}
